#include <iostream>
#include <string>
#include <iomanip>
#include <stdexcept>

// Abstract Base Class
class Employee {
public:
    Employee(const std::string& first, const std::string& last, const std::string& ssn)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {}

    virtual ~Employee() = default;

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    virtual double earnings() const = 0; // Pure virtual function

    virtual void print() const {
        std::cout << getFirstName() << " " << getLastName() 
                  << "\nsocial security number: " << getSocialSecurityNumber();
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

// Concrete Derived Class: SalariedEmployee
class SalariedEmployee : public Employee {
public:
    SalariedEmployee(const std::string& first, const std::string& last, 
                     const std::string& ssn, double salary = 0.0)
        : Employee(first, last, ssn) {
        setWeeklySalary(salary);
    }

    void setWeeklySalary(double salary) {
        if (salary >= 0.0) {
            weeklySalary = salary;
        } else {
            throw std::invalid_argument("Weekly salary must be >= 0.0");
        }
    }

    double getWeeklySalary() const { return weeklySalary; }

    virtual double earnings() const override {
        return getWeeklySalary();
    }

    virtual void print() const override {
        std::cout << "salaried employee: ";
        Employee::print(); // Code reuse via scope resolution
        std::cout << "\nweekly salary: " << getWeeklySalary();
    }

private:
    double weeklySalary{0.0};
};

// Concrete Derived Class: CommissionEmployee
class CommissionEmployee : public Employee {
public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales = 0.0, double rate = 0.0)
        : Employee(first, last, ssn) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setGrossSales(double sales) {
        if (sales >= 0.0) {
            grossSales = sales;
        } else {
            throw std::invalid_argument("Gross sales must be >= 0.0");
        }
    }

    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate > 0.0 && rate < 1.0) {
            commissionRate = rate;
        } else {
            throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        }
    }

    double getCommissionRate() const { return commissionRate; }

    virtual double earnings() const override {
        return getCommissionRate() * getGrossSales();
    }

    virtual void print() const override {
        std::cout << "commission employee: ";
        Employee::print(); // Code reuse
        std::cout << "\ngross sales: " << getGrossSales()
                  << "; commission rate: " << getCommissionRate();
    }

private:
    double grossSales{0.0};
    double commissionRate{0.0};
};

// Indirect Concrete Derived Class: BasePlusCommissionEmployee
class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(const std::string& first, const std::string& last,
                               const std::string& ssn, double sales = 0.0, 
                               double rate = 0.0, double salary = 0.0)
        : CommissionEmployee(first, last, ssn, sales, rate) {
        setBaseSalary(salary);
    }

    void setBaseSalary(double salary) {
        if (salary >= 0.0) {
            baseSalary = salary;
        } else {
            throw std::invalid_argument("Salary must be >= 0.0");
        }
    }

    double getBaseSalary() const { return baseSalary;
    }

    virtual double earnings() const override {
        return getBaseSalary() + CommissionEmployee::earnings(); // Code reuse
    }

    virtual void print() const override {
        std::cout << "base-salaried ";
        CommissionEmployee::print(); // Delegates to parent print
        std::cout << "; base salary: " << getBaseSalary();
    }

private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    SalariedEmployee salaried("John", "Smith", "111-11-1111", 800.0);
    CommissionEmployee commission("Sue", "Jones", "222-22-2222", 10000.0, 0.06);
    BasePlusCommissionEmployee basePlus("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    salaried.print();
    std::cout << "\nearnings: " << salaried.earnings() << "\n\n";

    commission.print();
    std::cout << "\nearnings: " << commission.earnings() << "\n\n";

    basePlus.print();
    std::cout << "\nearnings: " << basePlus.earnings() << "\n";

    return 0;
}
